<?php
namespace App\Models;use Illuminate\Database\Eloquent\{Builder,Model};
class TransportDocument extends Model {protected$fillable=['company_id','transport_document_type_id','resource_type','resource_id','resource_name_snapshot','document_number','issued_at','expires_at','file_path','file_hash','original_name','mime_type','notes','supersedes_document_id','is_current','created_by','updated_by'];protected$casts=['issued_at'=>'date','expires_at'=>'date','is_current'=>'boolean'];public function scopeForCompany(Builder$q,int$id):Builder{return$q->where('company_id',$id);}public function type(){return$this->belongsTo(TransportDocumentType::class,'transport_document_type_id');}public function previous(){return$this->belongsTo(self::class,'supersedes_document_id');}public function getControlStatusAttribute():string{if(!$this->expires_at)return'valid';if($this->expires_at->isPast())return'expired';$days=$this->type?->warning_days??30;return today()->diffInDays($this->expires_at,false)<=$days?'expiring':'valid';}}
